<h1>Dashboard</h1><p>Last login: <?= e($user['last_login'] ?? 'Never') ?></p><div class="stats"><?php foreach($stats as $k=>$v): ?><div class="card"><strong><?= e(ucfirst($k)) ?></strong><br><?= (int)$v ?></div><?php endforeach; ?></div><p><a class="btn" href="<?= e(url('admin/?action=posts')) ?>">Manage Posts</a> <a class="btn" href="<?= e(url('admin/?action=categories')) ?>">Manage Categories</a> <?php if(has_role('admin')): ?><a class="btn" href="<?= e(url('admin/?action=users')) ?>">Manage Users</a><?php endif; ?></p><section class="grid"><div class="card"><h2>Recent Posts</h2><?php foreach($recentPosts as $p): ?><p><?= e($p['title']) ?> — <?= e($p['created_at']) ?></p><?php endforeach; ?></div><div class="card"><h2>Recent Users</h2><?php foreach($recentUsers as $u): ?><p><?= e($u['username']) ?> — <?= e($u['created_at']) ?></p><?php endforeach; ?></div></section>
